25:     static int schemaVersion() {
26:         String property = System.getProperty(PROPERTY);
27:         String value = property != null ? property : System.getenv(ENVIRONMENT);
28:         if (value == null) return 0;
29:         try {
30:             int parsed = Integer.parseInt(value);
31:             return parsed >= VITAL_ARMOR_SCHEMA_VERSION
32:                     && parsed <= ELEMENTAL_RESISTANCE_SCHEMA_VERSION ? parsed : 0;
33:         } catch (NumberFormatException ignored) {
34:             return 0;
35:         }
36:     }
